// Generates tokens.mjs, tokens.d.ts and tokens.css from 18_DESIGN_SYSTEM/tokens.json.
//   node build.mjs          # write
//   node build.mjs --check  # exit 1 if a generated file is stale or a contrast rule fails
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { contrastFailures, resolveThemes } from "./contrast.mjs";

const HERE = fileURLToPath(new URL(".", import.meta.url));
const SOURCE = fileURLToPath(new URL("../../18_DESIGN_SYSTEM/tokens.json", import.meta.url));
const HEADER = "GENERATED by packages/tokens/build.mjs from 18_DESIGN_SYSTEM/tokens.json. Do not edit.";
const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

export function render(doc) {
  const themes = resolveThemes(doc);
  const palette = { ...doc.color, ...Object.fromEntries(Object.entries(doc.derivedColor).map(([k, v]) => [k, v.hex])) };
  const data = {
    version: doc.version,
    palette,
    themes,
    typography: doc.typography,
    space: doc.space,
    radius: doc.radius,
    motionMs: doc.motionMs,
    touchTargetDp: doc.touchTargetDp,
  };
  const mjs = `// ${HEADER}\nexport const tokens = Object.freeze(${JSON.stringify(data, null, 2)});\nexport default tokens;\n`;
  const roles = Object.keys(themes.dark);
  const dts = [
    `// ${HEADER}`,
    `export type ThemeName = ${Object.keys(themes).map((t) => JSON.stringify(t)).join(" | ")};`,
    `export type SemanticRole = ${roles.map((r) => JSON.stringify(r)).join(" | ")};`,
    "export interface Tokens {",
    "  readonly version: string;",
    "  readonly palette: Readonly<Record<string, string>>;",
    "  readonly themes: Readonly<Record<ThemeName, Readonly<Record<SemanticRole, string>>>>;",
    "  readonly typography: { readonly display: string; readonly body: string; readonly technical: string; readonly fallback: string; readonly scale: readonly number[] };",
    "  readonly space: readonly number[];",
    "  readonly radius: readonly number[];",
    "  readonly motionMs: readonly number[];",
    "  readonly touchTargetDp: number;",
    "}",
    "export declare const tokens: Tokens;",
    "export default tokens;",
    "",
  ].join("\n");
  const vars = (theme) => roles.map((r) => `  --aurea-color-${kebab(r)}: ${themes[theme][r]};`).join("\n");
  const font = (f) => `"${f}", ${doc.typography.fallback}`;
  const css = [
    `/* ${HEADER} */`,
    ":root {",
    ...doc.space.map((v, i) => `  --aurea-space-${i + 1}: ${v}px;`),
    ...doc.radius.map((v, i) => `  --aurea-radius-${i + 1}: ${v}px;`),
    ...doc.typography.scale.map((v, i) => `  --aurea-font-size-${i + 1}: ${v / 16}rem;`),
    `  --aurea-font-display: ${font(doc.typography.display)};`,
    `  --aurea-font-body: ${font(doc.typography.body)};`,
    `  --aurea-font-technical: "${doc.typography.technical}", ui-monospace, monospace;`,
    ...doc.motionMs.map((v, i) => `  --aurea-motion-${i + 1}: ${v}ms;`),
    `  --aurea-touch-target: ${doc.touchTargetDp}px;`,
    "}",
    "/* Dark (black and gold) is the brand default (DESIGN.md); light is opt-in with data-theme=\"light\". */",
    `:root, [data-theme="dark"] {\n  color-scheme: dark;\n${vars("dark")}\n}`,
    `[data-theme="light"] {\n  color-scheme: light;\n${vars("light")}\n}`,
    `@media (prefers-reduced-motion: reduce) {\n  :root {\n${doc.motionMs.map((_, i) => `    --aurea-motion-${i + 1}: 0ms;`).join("\n")}\n  }\n}`,
    "",
  ].join("\n");
  return { "tokens.mjs": mjs, "tokens.d.ts": dts, "tokens.css": css };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const doc = JSON.parse(readFileSync(SOURCE, "utf8"));
  const failures = contrastFailures(doc);
  if (failures.length) {
    console.error(`contrast below WCAG 2.2 AA:\n${failures.join("\n")}`);
    process.exit(1);
  }
  const out = render(doc);
  if (process.argv.includes("--check")) {
    const stale = Object.entries(out).filter(([f, text]) => {
      try { return readFileSync(`${HERE}${f}`, "utf8") !== text; } catch { return true; }
    });
    for (const [f] of stale) console.error(`packages/tokens/${f} is stale: run pnpm --filter @aurea/tokens build`);
    if (stale.length) process.exit(1);
    console.log("tokens OK: generated files current, every contrast rule passes");
  } else {
    for (const [f, text] of Object.entries(out)) writeFileSync(`${HERE}${f}`, text);
    console.log(`wrote ${Object.keys(out).join(", ")}`);
  }
}
